// { es: { English: Spanish, … }, fr: …, de: …, nl: … }
export const ZONE_TEXT = Object.fromEntries(ORDER.map((l, i) => [l,
  Object.fromEntries(ZONE_ROWS.filter((r) => r[i + 1]).map((r) => [r[0], r[i + 1]]))]));

// Language of the zone: the cookie set in Settings → Language, else the browser's language, else English.
export function zoneLang(request) {
  const ok = (l) => ZONE_LANGS.some(([c]) => c === l);
  const m = (request.headers.get("Cookie") || "").match(/(?:^|;\s*)talay-zone-lang=([a-z]{2})/);
  if (m && ok(m[1])) return m[1];
  for (const part of (request.headers.get("Accept-Language") || "").split(",")) {
    const l = part.trim().slice(0, 2).toLowerCase();
    if (ok(l)) return l;
  }
  return "en";
}

// T("Save") → "Guardar"; T("Pause {a}", { a: "Mia" }) → "Pausar a Mia". Values are inserted as given (escape them first).
export function zoneT(lang) {
  const dict = ZONE_TEXT[lang] || {};
  return (s, v) => {
    const x = dict[s] || s;
    return v ? x.replace(/\{(\w+)\}/g, (m, k) => (k in v ? v[k] : m)) : x;
  };
}
